package org.multipaz.facenet

import kotlinx.io.bytestring.ByteString
import kotlin.io.encoding.Base64
import kotlin.io.encoding.ExperimentalEncodingApi

/**
 * Embedded binary data for MiniFASNetV2 passive face anti-spoofing model
 * (2.7_80x80_MiniFASNetV2 from Silent-Face-Anti-Spoofing, Apache-2.0 license,
 * converted to FP16 TFLite with RGB [0, 255] input and 3-class softmax output).
 */
object MiniFasNetModelData {
    private val BASE64_CHUNKS = arrayOf(
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        ""
    )

    @OptIn(ExperimentalEncodingApi::class)
    val defaultModelBytes: ByteString by lazy {
        val combined = BASE64_CHUNKS.joinToString("")
        ByteString(Base64.decode(combined))
    }
}
